CREATE TABLE patients (patient_id INTEGER PRIMARY KEY, first_name TEXT, last_name TEXT, gender TEXT, birth_date TEXT, city TEXT, insurance TEXT);
CREATE TABLE doctors (doctor_id INTEGER PRIMARY KEY, name TEXT, specialty TEXT, hire_date TEXT, visit_fee INTEGER);
CREATE TABLE appointments (appt_id INTEGER PRIMARY KEY, patient_id INTEGER REFERENCES patients(patient_id), doctor_id INTEGER REFERENCES doctors(doctor_id), appt_date TEXT, status TEXT, reason TEXT, fee INTEGER);
CREATE TABLE prescriptions (rx_id INTEGER PRIMARY KEY, appt_id INTEGER REFERENCES appointments(appt_id), drug TEXT, days_supply INTEGER, cost REAL);
CREATE TABLE lab_results (result_id INTEGER PRIMARY KEY, patient_id INTEGER REFERENCES patients(patient_id), test TEXT, value REAL, result_date TEXT);
